package bookstore

import "sort"

// Cost returns the total cost, in cents, of the books in the basket,
// applying as big a discount as possible.
//
// Each book is identified by an integer 1-5. One copy costs 800 cents;
// a group of n different books is discounted as follows:
//
//	1 book:  800 each
//	2 books: 5% off  -> 1520 total
//	3 books: 10% off -> 2160 total
//	4 books: 20% off -> 2560 total
//	5 books: 25% off -> 3000 total
func Cost(books []int) int {
	var counts [5]int
	for _, b := range books {
		if b >= 1 && b <= 5 {
			counts[b-1]++
		}
	}
	sort.Slice(counts[:], func(i, j int) bool { return counts[i] > counts[j] })

	// Price of a group, in cents, indexed by group size.
	var prices = [6]int{0, 800, 1520, 2160, 2560, 3000}

	total := 0
	for counts[0] > 0 {
		// Number of distinct titles still available.
		n := 0
		for _, c := range counts {
			if c > 0 {
				n++
			} else {
				break
			}
		}
		// With five distinct titles, a group of four is cheaper overall than
		// a group of five when the third count exceeds the fourth: two groups
		// of four cost 5120, while a group of five plus a group of three costs
		// 5160. Leaving the rarest title out lets it join a later group of four.
		if n == 5 && counts[2] > counts[3] {
			n = 4
		}
		total += prices[n]
		for i := 0; i < n; i++ {
			counts[i]--
		}
		sort.Slice(counts[:], func(i, j int) bool { return counts[i] > counts[j] })
	}
	return total
}

